/* eslint-disable @typescript-eslint/naming-convention */
import { Component, OnInit } from '@angular/core';
import { FormBuilder, FormGroup, Validators } from '@angular/forms';
import { AlertController, LoadingController, ToastController } from '@ionic/angular';
import { SliderService } from '../../../../../data/service/site/Slider.service';
import { DoerModel, IDoerModel } from '../../../../../data/model/site/SliderModel';
import { SharedIonic } from '../../../../../core/common/SharedIonic';
import { GResponse } from '../../../../../core/common/GResponse';
import { ItemReorderEventDetail } from '@ionic/angular';

@Component({
  selector: 'app-doer',
  templateUrl: './doer.component.html',
  styleUrls: ['./doer.component.scss']
})
export class DoerComponent implements OnInit {

  addForm: FormGroup;
  updateForm: FormGroup;
  doers: IDoerModel[];
  segmentSelected = 'Update';

  constructor(
    private sliderService: SliderService,
    private fb: FormBuilder,
    public toastController: ToastController,
    public loadingController: LoadingController,
    public alertController: AlertController
  ) { }

  ngOnInit(): void {

    this.addForm = this.fb.group({
      name: ['', [Validators.required, Validators.maxLength(1000000)]],
      family: ['', [Validators.maxLength(1000000)]],
      brand: ['', [Validators.maxLength(1000000)]],
      image: ['Default-Doer', [Validators.required, Validators.maxLength(1000000)]],
      address: ['', [Validators.maxLength(1000000)]],
      addressLocation: ['', [Validators.maxLength(1000000)]],
      instagram: ['', [Validators.maxLength(1000)]],
      phone: ['', [Validators.required, Validators.maxLength(30)]],
      point: ['5', [Validators.required, Validators.maxLength(30)]],
      isActive: [true, [Validators.required]]
    });

    this.updateForm = this.fb.group({
      id: ['', [Validators.required, Validators.min(1)]],
      name: ['', [Validators.maxLength(1000000)]],
      family: ['', [Validators.maxLength(1000000)]],
      brand: ['', [Validators.maxLength(1000000)]],
      image: ['Default-Doer', [Validators.required, Validators.maxLength(1000000)]],
      address: ['', [Validators.maxLength(1000000)]],
      addressLocation: ['', [Validators.maxLength(1000000)]],
      instagram: ['', [Validators.required, Validators.maxLength(1000)]],
      phone: ['', [Validators.required, Validators.maxLength(30)]],
      order: ['', [Validators.required, Validators.maxLength(30)]],
      point: ['', [Validators.required, Validators.maxLength(30)]],
      isActive: [true, [Validators.required]]
    });
  }

  ionViewWillEnter() {

    this.onGetData();
  }

  handleReorder(ev: CustomEvent<ItemReorderEventDetail>) {
    // Before complete is called with the items they will remain in the
    // order before the drag
    //console.log('Before complete', this.courseDetail.courseVideos);

    // Finish the reorder and position the item in the DOM based on
    // where the gesture ended. Update the items variable to the
    // new order of items
    this.doers = ev.detail.complete(this.doers);

    let count = 0;
    this.doers.forEach(c => {

      this.doers[count].order = count;
      count++;
    });
    // After complete is called the items will be in the new order
    // console.log('After complete', this.courseDetail.courseVideos);
  }

  onOrderSet() {

    SharedIonic.loading(this.loadingController);

    this.sliderService.AdminUpdateDoerOrder(
      this.doers
    ).subscribe(
      res => {
        SharedIonic.dismissLoading(this.loadingController);
        if (GResponse.SuccessStatus === res.status) {

          SharedIonic.successToast(this.toastController);
          location.reload();
        } else {
          SharedIonic.unSuccessToast(this.toastController);
        }
      },
      err => {
        SharedIonic.dismissLoading(this.loadingController);
        SharedIonic.unSuccessToast(this.toastController);
      }
    );
  }

  onGetData() {

    SharedIonic.loading(this.loadingController);

    this.sliderService.AdminGetAllDoers().subscribe(
      res => {
        SharedIonic.dismissLoading(this.loadingController);
        if (res.status === GResponse.SuccessStatus) {

          this.doers = res.data;
        } else {
          SharedIonic.unSuccessToast(this.toastController);
        }
      },
      err => {
        SharedIonic.dismissLoading(this.loadingController);
        SharedIonic.unSuccessToast(this.toastController);
      }
    );
  }

  onSelect(index: number | string): void {

    this.updateForm.setValue({
      id: this.doers[+index].id,
      name: this.doers[+index].name,
      family: this.doers[+index].family,
      brand: this.doers[+index].brand,
      image: this.doers[+index].image,
      address: this.doers[+index].address,
      addressLocation: this.doers[+index].addressLocation,
      instagram: this.doers[+index].instagram,
      phone: this.doers[+index].phone,
      isActive: this.doers[+index].isActive,
      order: this.doers[+index].order,
      point: this.doers[+index].point
    });
  }

  onUpdate() {

    if (this.updateForm.valid) {

      SharedIonic.loading(this.loadingController);

      this.sliderService.AddOrUpdateDoer(
        new DoerModel(
          this.updateForm.value.id,
          this.updateForm.value.name,
          this.updateForm.value.family,
          this.updateForm.value.brand,
          this.updateForm.value.image,
          this.updateForm.value.address,
          this.updateForm.value.addressLocation,
          this.updateForm.value.instagram,
          this.updateForm.value.phone,
          this.updateForm.value.isActive,
          this.updateForm.value.point,
          this.updateForm.value.order
        )
      ).subscribe(
        res => {
          SharedIonic.dismissLoading(this.loadingController);
          if (res.status === GResponse.SuccessStatus) {

            this.updateForm.setValue({
              id: '',
              name: '',
              family: '',
              brand: '',
              image: '',
              address: '',
              addressLocation: '',
              instagram: '',
              phone: '',
              isActive: false,
              order: '',
              point: ''
            });
            this.onGetData();
            SharedIonic.successToast(this.toastController);
          } else {
            SharedIonic.unSuccessToast(this.toastController);
          }
        },
        err => {
          SharedIonic.dismissLoading(this.loadingController);
          SharedIonic.unSuccessToast(this.toastController);
        }
      );
    }
  }

  onAdd() {

    if (this.addForm.valid) {

      SharedIonic.loading(this.loadingController);

      this.sliderService.AddOrUpdateDoer(
        new DoerModel(
          0,
          this.addForm.value.name,
          this.addForm.value.family,
          this.addForm.value.brand,
          this.addForm.value.image,
          this.addForm.value.address,
          this.addForm.value.addressLocation,
          this.addForm.value.instagram,
          this.addForm.value.phone,
          this.addForm.value.isActive,
          this.addForm.value.point,
          0
        )
      ).subscribe(
        res => {
          SharedIonic.dismissLoading(this.loadingController);
          if (res.status === GResponse.SuccessStatus) {

            this.addForm.setValue({
              name: '',
              family: '',
              brand: '',
              image: '',
              address: '',
              addressLocation: '',
              instagram: '',
              phone: '',
              isActive: false,
              point: ''
            });
            this.onGetData();
            SharedIonic.successToast(this.toastController);
          } else {
            SharedIonic.unSuccessToast(this.toastController);
          }
        },
        err => {
          SharedIonic.dismissLoading(this.loadingController);
          SharedIonic.unSuccessToast(this.toastController);
        }
      );
    }
  }

  async presentAlertConfirm3() {
    const alert = await this.alertController.create({
      cssClass: 'main-alert',
      header: 'هشدار!',
      message: 'آیا مطمئن به آپدیت هستید؟',
      buttons: [
        {
          text: 'لغو',
          role: 'cancel',
          cssClass: 'secondary',
          handler: () => {
          }
        }, {
          text: 'بله',
          handler: () => {
            this.onAdd();
          }
        }
      ]
    });

    await alert.present();
  }

  async presentAlertConfirm2() {
    const alert = await this.alertController.create({
      cssClass: 'main-alert',
      header: 'هشدار!',
      message: 'آیا مطمئن به آپدیت هستید؟',
      buttons: [
        {
          text: 'لغو',
          role: 'cancel',
          cssClass: 'secondary',
          handler: () => {
          }
        }, {
          text: 'بله',
          handler: () => {
            this.onUpdate();
          }
        }
      ]
    });

    await alert.present();
  }

  async presentAlertConfirm(id: number | string) {
    const alert = await this.alertController.create({
      cssClass: 'main-alert',
      header: 'هشدار!',
      message: 'آیا مطمئن به حذف هستید؟!؟',
      buttons: [
        {
          text: 'لغو',
          role: 'cancel',
          cssClass: 'secondary',
          handler: () => {
          }
        }, {
          text: 'حذف',
          handler: () => {
            this.onRemove(+id);
          }
        }
      ]
    });

    await alert.present();
  }

  onRemove(id: number) {

    SharedIonic.loading(this.loadingController);

    this.sliderService.RemoveDoer(id).subscribe(
      res => {
        SharedIonic.dismissLoading(this.loadingController);
        if (res.status === GResponse.SuccessStatus) {

          this.updateForm.setValue({
            id: '',
            name: '',
            family: '',
            brand: '',
            image: '',
            address: '',
            addressLocation: '',
            instagram: '',
            phone: '',
            isActive: false,
            order: '',
            point: ''
          });
          this.onGetData();
          SharedIonic.successToast(this.toastController);
        } else {
          SharedIonic.unSuccessToast(this.toastController);
        }
      },
      err => {
        SharedIonic.dismissLoading(this.loadingController);
        SharedIonic.unSuccessToast(this.toastController);
      }
    );
  }

}
